package br.com.loja.checkout;

import java.math.BigDecimal;
import java.math.RoundingMode;

/** Arredondamento de valores em dinheiro: centavos, "meio para o par". */
public final class Dinheiro {

    public static final BigDecimal ZERO = centavos(BigDecimal.ZERO);

    private Dinheiro() {
    }

    public static BigDecimal centavos(BigDecimal valor) {
        return valor.setScale(2, RoundingMode.HALF_EVEN);
    }

    /** Porcentagem (ex.: 2.5 para 2,5%) sobre o valor, arredondada para centavos. */
    public static BigDecimal percentual(BigDecimal valor, BigDecimal porcentagem) {
        return centavos(valor.multiply(porcentagem).movePointLeft(2));
    }
}
EOF
